413	async function provision(job: Job) {
414	  const server = await loadServer(job);
415	  // Clear any stale failure reason from a previous attempt as this run starts, so
416	  // a successful retry doesn't leave the last error hanging around on the row.
417	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING", provisionError: null } });
418	
419	  if (SANDBOX) {
420	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
421	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
422	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
423	    const password = generatePassword();
424	    const ip = sandboxIp(vmid);
425	    await db.server.update({
426	      where: { id: server.id },
427	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
428	    });
429	    await notify(
430	      server.userId,
431	      `Server ${server.hostname} is ready`,
432	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
433	      `/dashboard/servers/${server.id}`
434	    );
435	    // Post-purchase review request (once per server, skipped if no profiles set).
436	    await sendReviewRequestForServer(server.id);
437	    return;
438	  }
439	
440	  const { conn, row: nodeRow } = await nodeFor(server);
441	  const storage = server.plan.storageTier === "hdd"
442	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
443	    : nodeRow?.storageNvme ?? "vmdata";
444	
445	  // Pick a vmid that does NOT still own a previous tenant's backup archives.
446	  // `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
447	  // server's vzdump archives, so the id freed by a deletion comes back carrying
448	  // the old owner's backups — which every backup surface then attributes to the
449	  // new customer (listBackups/requestRestore key on vmid alone). See
450	  // `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
451	  // keeps the vmid already persisted on the row.
452	  const vmid = server.vmid ?? (await allocateFreshVmid(conn));
453	  const password = generatePassword();
454	
455	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
456	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
457	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
458	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
459	  const { getSettingBool: _settingBool } = await import("../lib/settings");
460	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
461	  if (wantDedicated && ovhConfigured()) {
462	    try {
463	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
464	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
465	      dedicated = await allocateDedicatedIp(server.id, vmid);
466	    } catch (e) {
467	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
468	    }
469	  }
470	  // Node-aware + transactionally-claimed allocation (passing the server id enables
471	  // the claim path, so two concurrent provisions can't pick the same IP/port).
472	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
473	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
474	
475	  await db.server.update({
476	    where: { id: server.id },
477	    data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
478	  });
479	
480	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
481	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
482	  // (worker restart mid-clone, or any transient failure in the steps below) would
483	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
484	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
485	  // the clone is idempotent, so skip it when the VM is already present.
486	  let vmAlreadyExists = false;
487	  try {
488	    await conn.vmStatus(vmid);
489	    vmAlreadyExists = true;
490	  } catch {
491	    vmAlreadyExists = false;
492	  }
493	  if (vmAlreadyExists) {
494	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
495	  } else {
496	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
497	      newid: vmid,
498	      name: server.hostname,
499	      full: 1,
500	      storage,
501	    });
502	    await conn.waitForTask(cloneUpid, 600_000);
503	  }
504	
505	  // Per-server cloud-init snippet (base + panel/app install + add-ons).
506	  //
507	  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
508	  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
509	  // failed write hands the VM a vendor-data file that does not exist. Root SSH
510	  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
511	  // all silently vanish, and the customer is still told the server is ready.
512	  // Failing here is recoverable — the job retries, and the clone above is
513	  // idempotent. Continuing is not.
514	  // NxCloud hook: if this VM is the backing box for a managed Nextcloud instance,
515	  // generate its one-time admin password (persisted, once) and get the idempotent
516	  // install script to bake into cloud-init. Null for an ordinary VPS.
517	  (server as any).__nxcloudSetup = await nxcloudSetupForServer(server);
518	  // Live telemetry: mint a fresh per-server shipper token and persist its hash
519	  // BEFORE building cloud-init, so the config the agent boots with matches what
520	  // the ingest route will look up (lib/telemetry-token.ts). Re-provisioning
521	  // (this code path runs again) simply mints a new token, invalidating the old
522	  // one — no rotation UI needed for that case.
523	  (server as any).__telemetryToken = await mintServerTelemetryToken(server.id);
524	
525	  const snippet = buildCloudInit(server);
526	  try {
527	    await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8");
528	  } catch (e: any) {
529	    throw new Error(
530	      `could not write the cloud-init snippet ${SNIPPET_DIR}/nxeon-${vmid}.yaml (${e?.message ?? e}). ` +
531	        `The VM would boot with no root password, no SSH key and no setup script, so provisioning ` +
532	        `stopped here rather than reporting a server that would not be usable.`
533	    );
534	  }
535	
536	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
537	  const sshkeys = keys.length
538	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
539	    : undefined;
540	  const cfg: Record<string, any> = {
541	    cores: server.plan.cpuCores,
542	    memory: server.plan.ramMB,
543	    ciuser: "root",
544	    cipassword: password,
545	    sshkeys,
546	    nameserver: "1.1.1.1 8.8.8.8",
547	    onboot: 1,
548	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
549	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
550	  };
551	  if (dedicated) {
552	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
553	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
554	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
555	  } else {
556	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
557	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
558	  }
559	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
560	
561	  // Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
562	  // customer bought as a deploy-time upsell, so the VM is born the right size and
563	  // no separate DISK_EXPAND job is needed on a fresh order.
564	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
565	    disk: "scsi0",
566	    size: `${effectiveDiskGB(server.plan.diskGB, server.extraDiskGB)}G`,
567	  });
568	
569	  // Port forwarding is what makes the `ssh root@host -p <port>` line below true
570	  // for a NAT server. If it cannot be proved, the readiness message says so
571	  // instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
572	  // VM itself is fine and a failed PROVISION would flip it to ERROR and release
573	  // its IP, which is a worse outcome than a missing forward.
574	  let natError: Error | null = null;
575	  if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);
576	
577	  // Idempotent start. A worker restart (e.g. a deploy) can interrupt a provision
578	  // AFTER the VM was already created and started; the reaper then re-queues the job.
579	  // Starting an already-running VM makes Proxmox's start task fail with "already
580	  // running", which — before this guard — stranded a perfectly good, reachable VM in
581	  // ERROR forever (every retry hit the same wall). So skip the start when the VM is
582	  // already running, and treat an "already running" race as success rather than fatal.
583	  const alreadyRunning = await conn
584	    .vmStatus(vmid)
585	    .then((s: { status?: string } | null) => s?.status === "running")
586	    .catch(() => false);
587	  if (!alreadyRunning) {
588	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
589	    try {
590	      await conn.waitForTask(startUpid);
591	    } catch (e) {
592	      if (!/already running/i.test(String((e as { message?: unknown })?.message ?? ""))) throw e;
593	    }
594	  }
595	
596	  // `waitForTask` proves Proxmox accepted the start, nothing more. Ask the guest
597	  // agent whether the machine actually booted before calling it ready (M7 #10).
598	  // A false here is reported, never downgraded into silence.
599	  const booted = SANDBOX ? true : await waitForGuestAgent(conn, conn.node, vmid);
600	
601	  // Real end-to-end reachability check — the guest agent above proves only that
602	  // QEMU's in-guest daemon answered (and plenty of images don't even ship it, see
603	  // the `booted` caveat below). Neither that nor `waitForTask` proves a customer
604	  // can actually reach the thing we are about to call "ready". Two real incidents
605	  // shipped without this: a VM whose IP collided with unrelated infrastructure
606	  // (nothing was ever reachable), and separately every game family's
607	  // `docker run -d` setup script creates no systemd unit, so the game process can
608	  // silently fail to start while the container still shows "Up" (confirmed:
609	  // Terraria hung on an interactive world-selection prompt with no TTY, port
610	  // never bound) — PROVISION reported success both times. This throws on
611	  // failure, same as every other fatal step above: the existing `runJob` catch
612	  // path (retry while attempts remain, else ERROR + release the dedicated IP +
613	  // `notifyProvisionFailed`) handles it, and because this runs BEFORE the
614	  // status flip to RUNNING and the deployment email below, neither ever fires
615	  // for a server that failed this check.
616	  if (!SANDBOX) {
617	    // Same address a customer would use: the dedicated IP if one was allocated,
618	    // else the NAT host's public IP + this server's assigned SSH port — reusing
619	    // `dedicated`/`sshPort` computed earlier rather than recomputing them (see
620	    // the identical `sshLine` construction below).
621	    const sshHost = dedicated ? dedicated.address : (server.node?.publicIp ?? process.env.PUBLIC_IP);
622	    const sshCheckPort = dedicated ? 22 : (sshPort ?? 22);
623	    const ssh = await checkSshReachable(sshHost!, sshCheckPort);
624	    if (!ssh.ok) {
625	      throw new Error(
626	        `SSH did not respond on ${sshHost}:${sshCheckPort} after ~${Math.round(ssh.elapsedMs / 1000)}s ` +
627	          `(${ssh.attempts} attempt(s); last error: ${ssh.error}). The VM started, but nothing answered SSH, ` +
628	          `so this server cannot be handed to the customer as ready.`
629	      );
630	    }
631	
632	    const game = gamePortForServer(server as unknown as ServerFamilyLike);
633	    if (game) {
634	      // `ip` is the dedicated public IP or the NAT server's private address —
635	      // already computed above. Only SSH gets an automatic NAT port-forward at
636	      // provision time; a game's own port is forwarded only if the customer adds
637	      // one (lib/actions-server.ts), a separate pre-existing gap this does not
638	      // touch. Checking against `ip` still proves what this check exists to
639	      // prove: the game process itself bound its port, independent of whether
640	      // that port has been forwarded to the internet yet.
641	      const gameCheck = await checkGamePortOpen(ip, game.port, game.protocol);
642	      if (!gameCheck.ok) {
643	        throw new Error(
644	          `game port ${game.port}/${game.protocol} never opened on ${ip} after ` +
645	            `~${Math.round(gameCheck.elapsedMs / 1000)}s (${gameCheck.attempts} attempt(s); last error: ` +
646	            `${gameCheck.error}). SSH is up, but the game server itself never started listening, so this ` +
647	            `server cannot be handed to the customer as ready.`
648	        );
649	      }
650	    } else if (server.gamePlanId) {
651	      // A game order whose family we could not map to a port (new game added to
652	      // GAME_FAMILIES/catalog without a matching lib/games.ts GAME_PORT entry).
653	      // This is a config gap, not evidence the server is unhealthy — log it
654	      // loudly for whoever ships the next game, but do not fail a customer's
655	      // order over our own missing map entry.
656	      console.error(
657	        `[worker] provision ${server.hostname}: game order (gamePlanId=${server.gamePlanId}, ` +
658	          `osTemplate.family=${server.osTemplate?.family ?? "?"}) has no GAME_PORT entry — skipped the game-port check`
659	      );
660	    }
661	  }
662	
663	  const runningServer = await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
664	
665	  // Deployment confirmation email (transactional, deduped via EmailLog). Runs on
666	  // the provision money-path, so it is best-effort and must never fail the build.
667	  try {
668	    const { sendServerDeployedEmail } = await import("../lib/server-deployed-email");
669	    await sendServerDeployedEmail(server, (server as any).user);
670	  } catch (e) {
671	    console.error("[worker] deployment-confirmation email failed (non-fatal)", e);
672	  }
673	  // Tell the partner (best-effort, never blocks provisioning) — only for orders
674	  // tagged via a partner deep link (see PartnerSourceCapture + payAndDeploy).
675	  // Most VPS orders are direct Nxeon customers and must never be forwarded to a
676	  // partner's webhook.
677	  if (runningServer.partnerSource === "kodely") {
678	    try {
679	      const { notifyPartner } = await import("../lib/partner");
680	      await notifyPartner("vps.provisioned", {
681	        userId: runningServer.userId,
682	        serverId: runningServer.id,
683	        hostname: runningServer.hostname,
684	        ipAddress: runningServer.ipAddress,
685	      });
686	    } catch (e) {
687	      console.error("[worker] partner notify failed (non-fatal)", e);
688	    }
689	  }
690	
691	  const isImage = server.osTemplate.category !== "PLAIN_OS";
692	  const sshLine = dedicated
693	    ? `ssh root@${dedicated.address}`
694	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
695	
696	  const caveats: string[] = [];
697	  if (natError) {
698	    caveats.push(
699	      `Port forwarding could NOT be confirmed for this server, so the SSH command above may not connect yet — ` +
700	        `we are not going to pretend otherwise. Support has been alerted (${natError.message.slice(0, 200)}).`
701	    );
702	  }
703	  if (!booted) {
704	    caveats.push(
705	      "The hypervisor started the VM, but its guest agent has not answered yet, so we cannot confirm the " +
706	        "operating system finished booting. Give it a few more minutes; if the SSH command still fails, open a ticket."
707	    );
708	  }
709	  const body = [
710	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
711	    ...caveats,
712	  ].join(" — ");
713	  await notify(
714	    server.userId,
715	    // Never assert "ready" for something we could not verify.
716	    caveats.length ? `Server ${server.hostname} is up, with caveats` : `Server ${server.hostname} is ready`,
717	    body,
718	    `/dashboard/servers/${server.id}`
719	  );
720	  // Post-purchase review request (once per server, skipped if no profiles set).
721	  await sendReviewRequestForServer(server.id);
722	}
