724	async function powerAction(job: Job, action: "start" | "stop" | "reboot") {
725	  const server = await loadServer(job);
726	  if (SANDBOX) {
727	    await db.server.update({
728	      where: { id: server.id },
729	      data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
730	    });
731	    return;
732	  }
733	  const { conn } = await nodeFor(server);
734	  const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/${action}`, {});
735	  await conn.waitForTask(upid);
736	  await db.server.update({
737	    where: { id: server.id },
738	    data: { status: action === "stop" ? "STOPPED" : "RUNNING" },
739	  });
740	}
741	
742	/**
743	 * Tear down a VM. Idempotent and verified — see `destroyVmIdempotent` in
744	 * lib/proxmox.ts for the incident and the ladder. The bare version of this
745	 * function threw on an already-absent VM, which is what made a retried REINSTALL
746	 * destroy a customer's server permanently.
747	 */
748	async function destroyVm(conn: any, vmid: number): Promise<DestroyOutcome> {
749	  const host: VmDestroyHost = {
750	    probe: async (id) => {
751	      try {
752	        await conn.vmStatus(id);
753	        return "present";
754	      } catch (e) {
755	        // Only a vmid-anchored "config does not exist" proves absence. Anything
756	        // else (auth, network, a locked node) is genuinely unknown and must not
757	        // be read as "already gone".
758	        return isVmAbsentError(e, id) ? "absent" : "unknown";
759	      }
760	    },
761	    stop: async (id) => {
762	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${id}/status/stop`, {});
763	      await conn.waitForTask(stopUpid);
764	    },
765	    destroy: async (id) => {
766	      const delUpid = await conn.del(`/nodes/${conn.node}/qemu/${id}`, {
767	        "destroy-unreferenced-disks": 1,
768	        purge: 1,
769	      });
770	      await conn.waitForTask(delUpid, 600_000);
771	    },
772	  };
773	  return destroyVmIdempotent(host, vmid);
774	}
775	
776	async function remove(job: Job) {
777	  const server = await loadServer(job);
778	  const { conn } = await nodeFor(server);
779	  if (!SANDBOX && server.vmid) {
780	    // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
781	    // so the absent case no longer needs to be caught here at all. The catch that
782	    // remains is narrowed to this vmid: it used to swallow any error containing
783	    // "does not exist", which also matches `storage 'vmdata' does not exist` and
784	    // `volume ... does not exist` — errors that mean the VM is very much still
785	    // running. On one of those the handler proceeded to delete the Server row and
786	    // every Volume row pinned to it, leaving a live VM with no database record:
787	    // invisible to billing, invisible to the panel, still holding the customer's
788	    // data and impossible to reach through any surface we own.
789	    try {
790	      await destroyVm(conn, server.vmid);
791	    } catch (e: any) {
792	      if (!isVmAbsentError(e, server.vmid)) throw e;
793	    }
794	    // Best-effort: remove the per-server cloud-init snippet
795	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
796	  }
797	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
798	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
799	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
800	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
801	  // diskName and keep billing forever. Remove them and notify the owner. (The
802	  // reinstall guard already blocks the accidental case; a full server delete is an
803	  // intentional teardown, so we drop the volumes with it.)
804	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
805	  if (orphanVolumes.length > 0) {
806	    await db.volume.deleteMany({ where: { serverId: server.id } });
807	    for (const v of orphanVolumes) {
808	      await notify(
809	        v.userId,
810	        `Volume "${v.name}" was removed`,
811	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
812	        "/dashboard/volumes",
813	      ).catch(() => {});
814	    }
815	  }
816	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
817	  // server.delete cascade removes THIS running Job row — the success-path
818	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
819	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
820	  await db.server.delete({ where: { id: server.id } });
821	  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
822	  // DELETE, which then dies on "Server not found" and the sync is never retried
823	  // (H5's aggravating factor). The failure is logged in full rather than hidden.
824	  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
825	}
826	
827	async function reinstall(job: Job) {
828	  const server = await loadServer(job);
829	  if (SANDBOX) {
830	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
831	    await notify(
832	      server.userId,
833	      `Server ${server.hostname} reinstalled (sandbox)`,
834	      "The sandbox server was reinstalled (no real VM was touched).",
835	      `/dashboard/servers/${server.id}`
836	    );
837	    return;
838	  }
839	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
840	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
841	  // EVERY disk the vmid owns, including attached block-storage Volume disks
842	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
843	  // by that vmid, and both purge and the default destroy (which removes disks
844	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
845	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
846	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
847	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
848	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
849	  // can be re-attached after the reinstall. This runs BEFORE any status change or
850	  // destructive call, so a blocked reinstall touches nothing.
851	  //
852	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
853	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
854	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
855	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
856	  // let the worst path through: fill a volume, Detach (the UI says "Data is
857	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
858	  // Detaching is therefore NOT sufficient protection, and telling the customer to
859	  // detach was wrong advice; they must delete the volume (which destroys just
860	  // that disk, deliberately) or move it to another server first.
