69	const IPV4 = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
70	
71	function validPort(n: unknown): n is number {
72	  return typeof n === "number" && Number.isInteger(n) && n >= 1 && n <= 65535;
73	}
