75	/**
76	 * Turn the fleet into the exact DNAT ruleset the chain should hold.
77	 *
78	 * Two things this refuses to do quietly:
79	 *
80	 *  1. Install a rule built from a field that is not a valid IPv4 address, port or
81	 *     protocol. `execFile` with an argv array is already injection-safe, but a
82	 *     malformed value produces an iptables error mid-run, which under the old
83	 *     flush-and-rebuild is what aborted the loop and blackholed everyone after
84	 *     it. Rejected rows are reported, not silently skipped.
85	 *  2. Install two rules claiming the same protocol/public port. iptables is
86	 *     first-match, so a duplicate silently sends one customer's traffic to
87	 *     another customer's VM. The first claimant (stable order) wins and the
88	 *     collision is reported so somebody can fix the allocation.
89	 */
90	export function planNatRules(servers: readonly ForwardSource[]): NatIntent {
91	  const rules: NatRule[] = [];
92	  const conflicts: NatConflict[] = [];
93	  const rejected: NatRejection[] = [];
94	  const claimed = new Map<string, { hostname: string; index: number }>();
95	
96	  const claim = (r: NatRule, hostname: string) => {
97	    const key = `${r.proto}/${r.dport}`;
98	    const prior = claimed.get(key);
99	    if (prior) {
100	      const c = conflicts.find((x) => x.proto === r.proto && x.dport === r.dport);
101	      if (c) c.losers.push(hostname);
102	      else conflicts.push({ proto: r.proto, dport: r.dport, winner: prior.hostname, losers: [hostname] });
103	      return;
104	    }
105	    claimed.set(key, { hostname, index: rules.length });
106	    rules.push(r);
107	  };
108	
109	  // Stable order: sorted by hostname, then by public port. iptables is
110	  // first-match on distinct ports so order does not affect behaviour, but a
111	  // deterministic order makes the diff, the logs and the tests readable.
112	  const ordered = [...servers].sort((a, b) => a.hostname.localeCompare(b.hostname));
113	
114	  for (const s of ordered) {
115	    if (!s.ipAddress || !IPV4.test(s.ipAddress)) {
116	      rejected.push({ hostname: s.hostname, reason: `private IP ${JSON.stringify(s.ipAddress)} is not a valid IPv4 address` });
117	      continue;
118	    }
119	    if (!validPort(s.sshPort)) {
120	      rejected.push({ hostname: s.hostname, reason: `SSH port ${JSON.stringify(s.sshPort)} is not a valid port` });
121	    } else {
122	      claim({ proto: "tcp", dport: s.sshPort, destIp: s.ipAddress, destPort: 22 }, s.hostname);
123	    }
124	
125	    for (const f of [...s.portForwards].sort((a, b) => a.publicPort - b.publicPort)) {
126	      const proto = String(f.protocol ?? "").toLowerCase();
127	      if (proto !== "tcp" && proto !== "udp") {
128	        rejected.push({ hostname: s.hostname, reason: `port forward protocol ${JSON.stringify(f.protocol)} is not tcp or udp` });
129	        continue;
130	      }
131	      if (!validPort(f.publicPort) || !validPort(f.guestPort)) {
132	        rejected.push({
133	          hostname: s.hostname,
134	          reason: `port forward ${JSON.stringify(f.publicPort)}->${JSON.stringify(f.guestPort)} has an out-of-range port`,
135	        });
136	        continue;
137	      }
138	      claim({ proto, dport: f.publicPort, destIp: s.ipAddress, destPort: f.guestPort }, s.hostname);
139	    }
140	  }
141	
142	  return { rules, conflicts, rejected };
143	}
