172	 * Anything in our chain we cannot parse is returned in `unparsed` and never
173	 * touched. Deleting a rule we do not understand is how you turn "a stray rule
174	 * exists" into "somebody's forwarding is gone", and we do not know enough to be
175	 * making that trade silently.
176	 */
177	export function parseChainRules(chain: string, sOutput: string): { rules: NatRule[]; unparsed: string[] } {
178	  const rules: NatRule[] = [];
179	  const unparsed: string[] = [];
180	  for (const raw of String(sOutput ?? "").split("\n")) {
181	    const line = raw.trim();
182	    if (!line) continue;
183	    if (!line.startsWith(`-A ${chain} `)) continue; // -N, and jumps in other chains
184	    const body = line.slice(`-A ${chain} `.length);
185	    const proto = /(?:^|\s)-p\s+(tcp|udp)(?:\s|$)/.exec(body)?.[1];
186	    const dport = /(?:^|\s)--dport\s+(\d{1,5})(?:\s|$)/.exec(body)?.[1];
187	    const dest = /(?:^|\s)--to-destination\s+(\d{1,3}(?:\.\d{1,3}){3}):(\d{1,5})(?:\s|$)/.exec(body);
188	    const isDnat = /(?:^|\s)-j\s+DNAT(?:\s|$)/.test(body);
189	    if (!proto || !dport || !dest || !isDnat) {
190	      unparsed.push(line);
191	      continue;
192	    }
193	    const r: NatRule = { proto, dport: Number(dport), destIp: dest[1], destPort: Number(dest[2]) };
194	    if (!validPort(r.dport) || !validPort(r.destPort) || !IPV4.test(r.destIp)) {
195	      unparsed.push(line);
196	      continue;
197	    }
198	    rules.push(r);
