/// A free Minecraft server — one per verified account, running as a Docker
/// container on the dedicated "freemc-host" VM (Server.hostname="freemc-host"),
/// NOT a Server row itself (this isn't a Proxmox VM). itzg/mc-router in front of
/// that VM routes `<subdomain>.<free_minecraft_domain>` to this container by
/// Docker label, auto-starting it on connect and auto-stopping it after idle —
/// see worker/free-minecraft.ts and lib/actions-free-minecraft.ts. Resource caps
/// (RAM/disk/idle timeout/max total) are admin-configurable Settings, not
/// columns here, so an operator can retune them without a migration.
model FreeMinecraftServer {
  id            String   @id @default(cuid())
  userId        String   @unique
  user          User     @relation(fields: [userId], references: [id], onDelete: Cascade)
  // Public-facing name: reachable at `<subdomain>.<free_minecraft_domain>`.

